-- MasterApp Phase 20: integration gateway, public API v1, webhooks and connectors.
alter table public.plans
 add column if not exists public_api_enabled boolean not null default false,
 add column if not exists webhooks_enabled boolean not null default false,
 add column if not exists marketplace_integrations_enabled boolean not null default false,
 add column if not exists developer_portal_enabled boolean not null default false,
 add column if not exists max_api_clients integer,
 add column if not exists max_webhook_endpoints integer;
alter table public.store_feature_flags
 add column if not exists public_api_enabled boolean not null default true,
 add column if not exists webhooks_enabled boolean not null default true,
 add column if not exists marketplace_integrations_enabled boolean not null default true,
 add column if not exists developer_portal_enabled boolean not null default true;

create table public.integrations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,
 provider text not null check(length(btrim(provider)) between 2 and 80),integration_type text not null check(integration_type in('marketplace','accounting','payments','logistics','crm','analytics','custom_api','webhook','other')),name text not null check(length(btrim(name)) between 2 and 120),status text not null default 'pending' check(status in('active','inactive','error','pending','disconnected')),
 vault_config_secret_id uuid,scopes text[] not null default '{}',sync_mode text not null default 'inbound' check(sync_mode in('inbound','outbound','bidirectional')),price_source text not null default 'masterapp' check(price_source in('masterapp','external')),availability_sync_enabled boolean not null default false,environment text not null default 'production' check(environment in('production','sandbox')),
 connected_at timestamptz,disconnected_at timestamptz,last_sync_at timestamptz,last_success_at timestamptz,last_error text,last_latency_ms integer,consecutive_failures integer not null default 0,circuit_open_until timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.integration_store_access(integration_id uuid not null references public.integrations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,created_at timestamptz not null default now(),primary key(integration_id,store_id));

create table public.api_clients(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null check(length(btrim(name)) between 2 and 120),client_id text not null unique check(client_id ~ '^cli_[a-zA-Z0-9]{20,64}$'),secret_hash text not null check(length(secret_hash)=64),secret_prefix text not null check(length(secret_prefix) between 8 and 32),previous_secret_hash text,previous_secret_expires_at timestamptz,status text not null default 'active' check(status in('active','inactive','revoked')),scopes text[] not null default '{}',all_stores boolean not null default false,environment text not null default 'production' check(environment in('production','sandbox')),rate_limit_per_minute integer not null default 120 check(rate_limit_per_minute between 10 and 3000),expires_at timestamptz,last_used_at timestamptz,last_rotated_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.api_client_store_access(api_client_id uuid not null references public.api_clients(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,created_at timestamptz not null default now(),primary key(api_client_id,store_id));
create table public.api_idempotency_keys(id uuid primary key default gen_random_uuid(),api_client_id uuid not null references public.api_clients(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,idempotency_key text not null check(length(idempotency_key) between 8 and 200),request_method text not null,request_path text not null,request_hash text not null,response_status integer,response_body jsonb,resource_type text,resource_id uuid,created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '24 hours'),unique(api_client_id,idempotency_key));
create table public.api_rate_limit_buckets(api_client_id uuid not null references public.api_clients(id) on delete cascade,bucket_start timestamptz not null,request_count integer not null default 0,primary key(api_client_id,bucket_start));
create table public.api_request_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,api_client_id uuid references public.api_clients(id) on delete set null,store_id uuid references public.establishments(id) on delete set null,request_id text not null,method text not null,path text not null,status_code integer not null,latency_ms integer not null default 0,ip_hash text,error_code text,created_at timestamptz not null default now());

create table public.webhook_endpoints(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,name text not null check(length(btrim(name)) between 2 and 120),url text not null check(url ~ '^https://'),vault_secret_id uuid,secret_prefix text not null,status text not null default 'active' check(status in('active','inactive','error')),subscribed_events text[] not null default '{}',environment text not null default 'production' check(environment in('production','sandbox')),last_delivery_at timestamptz,last_success_at timestamptz,last_error text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.integration_events(id text primary key check(id ~ '^evt_[a-zA-Z0-9]{20,64}$'),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,event_type text not null,aggregate_type text,aggregate_id uuid,origin text not null default 'masterapp',correlation_id text,payload jsonb not null default '{}',environment text not null default 'production' check(environment in('production','sandbox')),created_at timestamptz not null default now());
create table public.webhook_deliveries(id uuid primary key default gen_random_uuid(),event_id text not null references public.integration_events(id) on delete cascade,endpoint_id uuid not null references public.webhook_endpoints(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,status text not null default 'pending' check(status in('pending','processing','delivered','failed','retrying')),attempt_count integer not null default 0,next_attempt_at timestamptz not null default now(),last_attempt_at timestamptz,delivered_at timestamptz,http_status integer,latency_ms integer,response_excerpt text,error_message text,request_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_id,endpoint_id));

create table public.external_product_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,integration_id uuid not null references public.integrations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,external_id text not null,internal_product_id uuid references public.products(id) on delete set null,external_name text,external_sku text,match_confidence numeric(5,4),mapping_status text not null default 'pending' check(mapping_status in('pending','suggested','confirmed','ignored')),last_sync_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(integration_id,store_id,external_id));
create table public.integration_status_mappings(id uuid primary key default gen_random_uuid(),integration_id uuid not null references public.integrations(id) on delete cascade,external_status text not null,internal_status text not null check(internal_status in('new','confirmed','preparing','ready','out_for_delivery','completed','canceled')),direction text not null default 'inbound' check(direction in('inbound','outbound')),created_at timestamptz not null default now(),unique(integration_id,direction,external_status));
create table public.integration_sync_jobs(id uuid primary key default gen_random_uuid(),integration_id uuid not null references public.integrations(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,job_type text not null,status text not null default 'pending' check(status in('pending','running','completed','failed','retrying')),attempt_count integer not null default 0,next_attempt_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,correlation_id text,payload jsonb not null default '{}',result jsonb,error_message text,created_at timestamptz not null default now());
create table public.integration_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,integration_id uuid references public.integrations(id) on delete set null,store_id uuid references public.establishments(id) on delete set null,event_type text not null check(event_type in('integration_request','integration_success','integration_failure','webhook_delivery','sync_started','sync_completed','credential_created','credential_rotated','credential_revoked','integration_connected','integration_disconnected','manual_reprocess')),level text not null default 'info' check(level in('info','warning','error')),request_id text,correlation_id text,latency_ms integer,message text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());

create index integrations_org_status_idx on public.integrations(organization_id,status,updated_at desc);
create index api_clients_org_status_idx on public.api_clients(organization_id,status,created_at desc);
create index api_request_logs_org_created_idx on public.api_request_logs(organization_id,created_at desc);
create index webhook_deliveries_due_idx on public.webhook_deliveries(status,next_attempt_at) where status in('pending','retrying');
create index webhook_deliveries_org_created_idx on public.webhook_deliveries(organization_id,created_at desc);
create index product_mappings_integration_idx on public.external_product_mappings(integration_id,mapping_status);
create index sync_jobs_due_idx on public.integration_sync_jobs(status,next_attempt_at) where status in('pending','retrying');
create index integration_logs_org_created_idx on public.integration_logs(organization_id,created_at desc);
create trigger integrations_touch before update on public.integrations for each row execute function public.touch_updated_at();
create trigger api_clients_touch before update on public.api_clients for each row execute function public.touch_updated_at();
create trigger webhook_endpoints_touch before update on public.webhook_endpoints for each row execute function public.touch_updated_at();
create trigger webhook_deliveries_touch before update on public.webhook_deliveries for each row execute function public.touch_updated_at();
create trigger external_product_mappings_touch before update on public.external_product_mappings for each row execute function public.touch_updated_at();

create or replace function private.integration_org_admin(target_org uuid) returns boolean language sql stable security definer set search_path='' as $$select private.is_superadmin() or exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=(select auth.uid()) and m.active and m.role in('owner','admin'))$$;
revoke all on function private.integration_org_admin(uuid) from public,anon,authenticated;grant execute on function private.integration_org_admin(uuid) to authenticated;

create or replace function public.consume_api_rate_limit(requested_client_id uuid,requested_limit integer) returns jsonb language plpgsql security definer set search_path='' as $$declare bucket timestamptz:=date_trunc('minute',clock_timestamp());used integer;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;insert into public.api_rate_limit_buckets(api_client_id,bucket_start,request_count)values(requested_client_id,bucket,1)on conflict(api_client_id,bucket_start)do update set request_count=public.api_rate_limit_buckets.request_count+1 returning request_count into used;return jsonb_build_object('allowed',used<=requested_limit,'limit',requested_limit,'remaining',greatest(requested_limit-used,0),'reset_at',extract(epoch from bucket+interval '1 minute')::bigint);end$$;
create or replace function public.create_webhook_endpoint_secret(requested_endpoint_id uuid,requested_secret text) returns uuid language plpgsql security definer set search_path='' as $$declare secret_id uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;if length(requested_secret)<32 or not exists(select 1 from public.webhook_endpoints where id=requested_endpoint_id) then raise exception 'Endpoint ou secret inválido.';end if;select vault.create_secret(requested_secret,'masterapp-webhook-'||requested_endpoint_id::text,'MasterApp webhook signing secret') into secret_id;update public.webhook_endpoints set vault_secret_id=secret_id where id=requested_endpoint_id;return secret_id;end$$;
create or replace function public.rotate_webhook_endpoint_secret(requested_endpoint_id uuid,requested_secret text) returns uuid language plpgsql security definer set search_path='' as $$declare old_id uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;select vault_secret_id into old_id from public.webhook_endpoints where id=requested_endpoint_id for update;if old_id is null then raise exception 'Endpoint não encontrado.';end if;perform vault.update_secret(old_id,requested_secret,null,'Rotated webhook secret');update public.webhook_endpoints set secret_prefix=left(requested_secret,12),updated_at=now()where id=requested_endpoint_id;return old_id;end$$;
create or replace function public.set_integration_config(requested_integration_id uuid,requested_config text) returns uuid language plpgsql security definer set search_path='' as $$declare old_id uuid;new_id uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;select vault_config_secret_id into old_id from public.integrations where id=requested_integration_id for update;if not found then raise exception 'Integração não encontrada.';end if;if old_id is null then select vault.create_secret(requested_config,'masterapp-integration-'||requested_integration_id::text,'Encrypted integration configuration')into new_id;else perform vault.update_secret(old_id,requested_config,null,'Encrypted integration configuration');new_id:=old_id;end if;update public.integrations set vault_config_secret_id=new_id,updated_at=now()where id=requested_integration_id;return new_id;end$$;

create or replace function public.claim_webhook_deliveries(requested_limit integer default 20) returns table(delivery_id uuid,event_id text,endpoint_id uuid,url text,event_type text,payload jsonb,signing_secret text,attempt_count integer,request_id text) language plpgsql security definer set search_path='' as $$begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;return query with claimed as(select d.id from public.webhook_deliveries d join public.webhook_endpoints e on e.id=d.endpoint_id where d.status in('pending','retrying')and d.next_attempt_at<=now()and e.status='active' order by d.next_attempt_at,d.created_at for update skip locked limit least(greatest(requested_limit,1),50)),updated as(update public.webhook_deliveries d set status='processing',attempt_count=d.attempt_count+1,last_attempt_at=now(),request_id=coalesce(d.request_id,'wh_'||replace(gen_random_uuid()::text,'-',''))from claimed c where d.id=c.id returning d.*)select u.id,u.event_id,u.endpoint_id,e.url,ev.event_type,ev.payload,v.decrypted_secret,u.attempt_count,u.request_id from updated u join public.webhook_endpoints e on e.id=u.endpoint_id join public.integration_events ev on ev.id=u.event_id join vault.decrypted_secrets v on v.id=e.vault_secret_id;end$$;
create or replace function public.finish_webhook_delivery(requested_delivery_id uuid,requested_success boolean,requested_http_status integer,requested_latency_ms integer,requested_response_excerpt text,requested_error text)returns void language plpgsql security definer set search_path='' as $$declare attempts integer;endpoint uuid;org uuid;next_delay interval;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;select attempt_count,endpoint_id,organization_id into attempts,endpoint,org from public.webhook_deliveries where id=requested_delivery_id for update;if requested_success then update public.webhook_deliveries set status='delivered',delivered_at=now(),http_status=requested_http_status,latency_ms=requested_latency_ms,response_excerpt=left(requested_response_excerpt,1000),error_message=null where id=requested_delivery_id;update public.webhook_endpoints set last_delivery_at=now(),last_success_at=now(),last_error=null where id=endpoint;else next_delay:=case attempts when 1 then interval'1 minute' when 2 then interval'5 minutes' when 3 then interval'30 minutes' else interval'2 hours'end;update public.webhook_deliveries set status=case when attempts>=5 then'failed'else'retrying'end,next_attempt_at=case when attempts>=5 then next_attempt_at else now()+next_delay end,http_status=requested_http_status,latency_ms=requested_latency_ms,response_excerpt=left(requested_response_excerpt,1000),error_message=left(requested_error,1000)where id=requested_delivery_id;update public.webhook_endpoints set last_delivery_at=now(),last_error=left(requested_error,1000),status=case when attempts>=5 then'error'else status end where id=endpoint;end if;insert into public.integration_logs(organization_id,event_type,level,request_id,latency_ms,message,metadata)values(org,'webhook_delivery',case when requested_success then'info'else'error'end,(select request_id from public.webhook_deliveries where id=requested_delivery_id),requested_latency_ms,case when requested_success then'Webhook entregue.'else'Falha na entrega do webhook.'end,jsonb_build_object('delivery_id',requested_delivery_id,'http_status',requested_http_status,'attempt',attempts));end$$;

create or replace function public.enqueue_integration_event(requested_organization_id uuid,requested_store_id uuid,requested_type text,requested_aggregate_type text,requested_aggregate_id uuid,requested_payload jsonb,requested_origin text default'masterapp',requested_correlation_id text default null,requested_environment text default'production')returns text language plpgsql security definer set search_path='' as $$declare event_key text:='evt_'||replace(gen_random_uuid()::text,'-','');begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;insert into public.integration_events(id,organization_id,store_id,event_type,aggregate_type,aggregate_id,origin,correlation_id,payload,environment)values(event_key,requested_organization_id,requested_store_id,requested_type,requested_aggregate_type,requested_aggregate_id,requested_origin,requested_correlation_id,coalesce(requested_payload,'{}'::jsonb),requested_environment);insert into public.webhook_deliveries(event_id,endpoint_id,organization_id)select event_key,e.id,e.organization_id from public.webhook_endpoints e where e.organization_id=requested_organization_id and e.status='active'and requested_type=any(e.subscribed_events)and(e.store_id is null or e.store_id=requested_store_id)and e.environment=requested_environment;return event_key;end$$;
create or replace function public.integration_create_order(requested_store_id uuid,requested_payload jsonb,requested_origin text,requested_correlation_id text,requested_environment text default'production')returns jsonb language plpgsql security definer set search_path='' as $$declare store_slug text;result jsonb;order_id uuid;org uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;if requested_environment='sandbox' then return jsonb_build_object('order_id','00000000-0000-0000-0000-000000000000','order_number',0,'status','sandbox','sandbox',true);end if;select slug,coalesce(organization_id,id)into store_slug,org from public.establishments where id=requested_store_id and active;if store_slug is null then raise exception'Unidade inválida.';end if;result:=public.place_public_order_v2(store_slug,requested_payload->>'customer_name',requested_payload->>'customer_phone',coalesce(requested_payload->>'fulfillment_type','pickup'),coalesce(requested_payload->'items','[]'::jsonb),requested_payload->>'notes',requested_payload->>'table_number','direct',requested_payload->>'payment_method',(requested_payload->>'cash_received_cents')::integer,requested_payload->'delivery_address');order_id:=(result->>'order_id')::uuid;update public.orders set source=case when requested_origin='marketplace'then'marketplace'else'custom_api'end,source_channel=case when requested_origin='marketplace'then'marketplace'else'api'end,order_source_channel=case when requested_origin='marketplace'then'marketplace'else'api'end where id=order_id;perform public.enqueue_integration_event(org,requested_store_id,'order.created','order',order_id,jsonb_build_object('order_id',order_id,'order_number',result->'order_number','status','new','total_cents',result->'total_cents','store_id',requested_store_id),requested_origin,requested_correlation_id,requested_environment);return result;end$$;
alter table public.orders drop constraint if exists orders_source_check;alter table public.orders add constraint orders_source_check check(source in('direct','qr','whatsapp','voice','web_chat','custom_api','marketplace'));

revoke all on function public.consume_api_rate_limit(uuid,integer),public.create_webhook_endpoint_secret(uuid,text),public.rotate_webhook_endpoint_secret(uuid,text),public.set_integration_config(uuid,text),public.claim_webhook_deliveries(integer),public.finish_webhook_delivery(uuid,boolean,integer,integer,text,text),public.enqueue_integration_event(uuid,uuid,text,text,uuid,jsonb,text,text,text),public.integration_create_order(uuid,jsonb,text,text,text)from public,anon,authenticated;
grant execute on function public.consume_api_rate_limit(uuid,integer),public.create_webhook_endpoint_secret(uuid,text),public.rotate_webhook_endpoint_secret(uuid,text),public.set_integration_config(uuid,text),public.claim_webhook_deliveries(integer),public.finish_webhook_delivery(uuid,boolean,integer,integer,text,text),public.enqueue_integration_event(uuid,uuid,text,text,uuid,jsonb,text,text,text),public.integration_create_order(uuid,jsonb,text,text,text)to service_role;

alter table public.integrations enable row level security;alter table public.integration_store_access enable row level security;alter table public.api_clients enable row level security;alter table public.api_client_store_access enable row level security;alter table public.api_idempotency_keys enable row level security;alter table public.api_rate_limit_buckets enable row level security;alter table public.api_request_logs enable row level security;alter table public.webhook_endpoints enable row level security;alter table public.integration_events enable row level security;alter table public.webhook_deliveries enable row level security;alter table public.external_product_mappings enable row level security;alter table public.integration_status_mappings enable row level security;alter table public.integration_sync_jobs enable row level security;alter table public.integration_logs enable row level security;
create policy integrations_admin_read on public.integrations for select to authenticated using(private.integration_org_admin(organization_id));create policy integration_store_access_admin_read on public.integration_store_access for select to authenticated using(exists(select 1 from public.integrations i where i.id=integration_id and private.integration_org_admin(i.organization_id)));create policy api_clients_admin_read on public.api_clients for select to authenticated using(private.integration_org_admin(organization_id));create policy api_client_store_admin_read on public.api_client_store_access for select to authenticated using(exists(select 1 from public.api_clients c where c.id=api_client_id and private.integration_org_admin(c.organization_id)));create policy api_request_logs_admin_read on public.api_request_logs for select to authenticated using(private.integration_org_admin(organization_id));create policy webhook_endpoints_admin_read on public.webhook_endpoints for select to authenticated using(private.integration_org_admin(organization_id));create policy integration_events_admin_read on public.integration_events for select to authenticated using(private.integration_org_admin(organization_id));create policy webhook_deliveries_admin_read on public.webhook_deliveries for select to authenticated using(private.integration_org_admin(organization_id));create policy product_mappings_admin_read on public.external_product_mappings for select to authenticated using(private.integration_org_admin(organization_id));create policy status_mappings_admin_read on public.integration_status_mappings for select to authenticated using(exists(select 1 from public.integrations i where i.id=integration_id and private.integration_org_admin(i.organization_id)));create policy sync_jobs_admin_read on public.integration_sync_jobs for select to authenticated using(private.integration_org_admin(organization_id));create policy integration_logs_admin_read on public.integration_logs for select to authenticated using(private.integration_org_admin(organization_id));
revoke all on public.integrations,public.integration_store_access,public.api_clients,public.api_client_store_access,public.api_idempotency_keys,public.api_rate_limit_buckets,public.api_request_logs,public.webhook_endpoints,public.integration_events,public.webhook_deliveries,public.external_product_mappings,public.integration_status_mappings,public.integration_sync_jobs,public.integration_logs from public,anon,authenticated;
grant select on public.integrations,public.integration_store_access,public.api_clients,public.api_client_store_access,public.api_request_logs,public.webhook_endpoints,public.integration_events,public.webhook_deliveries,public.external_product_mappings,public.integration_status_mappings,public.integration_sync_jobs,public.integration_logs to authenticated;
update public.plans set developer_portal_enabled=true where active;

create table if not exists private.integration_worker_settings(id boolean primary key default true check(id),worker_token_hash text not null,vault_secret_id uuid not null,created_at timestamptz not null default now());
do $$declare raw_token text:=encode(extensions.gen_random_bytes(32),'hex');sid uuid;begin select vault.create_secret(raw_token,'masterapp-phase20-worker','Phase 20 webhook worker credential')into sid;insert into private.integration_worker_settings(id,worker_token_hash,vault_secret_id)values(true,encode(extensions.digest(raw_token,'sha256'),'hex'),sid)on conflict(id)do nothing;end$$;
create or replace function public.verify_integration_worker_token(requested_token text)returns boolean language sql stable security definer set search_path='' as $$select current_setting('request.jwt.claim.role',true)='service_role'and exists(select 1 from private.integration_worker_settings where worker_token_hash=encode(extensions.digest(requested_token,'sha256'),'hex'))$$;
revoke all on function public.verify_integration_worker_token(text)from public,anon,authenticated;grant execute on function public.verify_integration_worker_token(text)to service_role;
do $$begin perform cron.unschedule('masterapp-phase20-webhook-worker')where exists(select 1 from cron.job where jobname='masterapp-phase20-webhook-worker');perform cron.schedule('masterapp-phase20-webhook-worker','* * * * *',$job$select net.http_post(url:='https://mesa-viva-patrilucas.patricklucas512.chatgpt.site/api/integrations/webhooks/process',headers:=jsonb_build_object('Content-Type','application/json','X-MasterApp-Worker',(select v.decrypted_secret from private.integration_worker_settings s join vault.decrypted_secrets v on v.id=s.vault_secret_id where s.id=true)),body:='{"limit":20}'::jsonb,timeout_milliseconds:=15000);$job$);end$$;
